import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type IncomeDepositProps = Record<string, any>;

const IncomeDeposit: React.FC<IncomeDepositProps> = ({
  backgroundColor = "#F4F7F6",
  transparentBackground = false,
  durationInSeconds = 6,
  bankName = "Malloy Bank",
  accountName = "Primary Checking",
  initialBalance = 12500,
  depositAmount = 3200,
  currencySymbol = "$",
  primaryColor = "#10B981",
  cardColor = "#0F172A",
  textColor = "#1E293B",
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations
  const safeZone = width * 0.05;
  const cardWidth = width * 0.28;
  const cardHeight = cardWidth * 0.63;

  // Animations
  // 1. Card Entrance
  const cardEntrance = spring({
    fps,
    frame,
    config: { damping: 14, stiffness: 80, mass: 1 },
  });
  const cardX = interpolate(cardEntrance, [0, 1], [-width * 0.5, 0]);
  const cardRotateY = interpolate(cardEntrance, [0, 1], [-45, 15]);
  const cardRotateX = interpolate(cardEntrance, [0, 1], [20, 5]);
  const cardOpacity = interpolate(cardEntrance, [0, 1], [0, 1]);

  // 2. Notification Pill Entrance
  const notifFrameStart = 30;
  const notifEntrance = spring({
    fps,
    frame: frame - notifFrameStart,
    config: { damping: 12, stiffness: 100 },
  });
  const notifY = interpolate(notifEntrance, [0, 1], [-100, 0]);
  const notifOpacity = interpolate(notifEntrance, [0, 0.5, 1], [0, 0, 1]);

  // 3. Balance Tick Up
  const tickStartFrame = 55;
  const tickEndFrame = 115;
  const tickProgress = interpolate(
    frame,
    [tickStartFrame, tickEndFrame],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  // Use easeOut-like interpolation for the counter
  const easeOutProgress = 1 - Math.pow(1 - tickProgress, 3);
  const currentBalance = Math.floor(
    initialBalance + depositAmount * easeOutProgress
  );

  // 4. Success Bounce
  const bounceFrameStart = tickEndFrame;
  const bounceScale = interpolate(
    frame,
    [bounceFrameStart, bounceFrameStart + 5, bounceFrameStart + 15],
    [1, 1.05, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 5. Background Graph Path Animation
  const graphProgress = spring({
    fps,
    frame: frame - tickStartFrame,
    config: { damping: 200, stiffness: 50 },
  });
  const pathLength = 1500;
  const dashOffset = pathLength - pathLength * graphProgress;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        overflow: "hidden",
      }}
    >
      {/* Background Decor */}
      <div
        style={{
          position: "absolute",
          top: "-20%",
          right: "-10%",
          width: width * 0.6,
          height: width * 0.6,
          background: `radial-gradient(circle, ${primaryColor}15 0%, ${primaryColor}00 70%)`,
          borderRadius: "50%",
          transition: "none",
        }}
      />
      <div
        style={{
          position: "absolute",
          bottom: "-30%",
          left: "-10%",
          width: width * 0.8,
          height: width * 0.8,
          background: `radial-gradient(circle, ${cardColor}08 0%, ${cardColor}00 70%)`,
          borderRadius: "50%",
          transition: "none",
        }}
      />

      {/* Main Content Container */}
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          width: "100%",
          height: "100%",
          alignItems: "center",
          justifyContent: "space-between",
          paddingLeft: safeZone * 2,
          paddingRight: safeZone * 2,
          transition: "none",
        }}
      >
        {/* Left Side: 3D Bank Card */}
        <div
          style={{
            flex: 1,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            perspective: "1200px",
            transition: "none",
          }}
        >
          <div
            style={{
              width: cardWidth,
              height: cardHeight,
              backgroundColor: cardColor,
              borderRadius: cardWidth * 0.06,
              boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.4)",
              padding: cardWidth * 0.08,
              display: "flex",
              flexDirection: "column",
              justifyContent: "space-between",
              transform: `translateX(${cardX}px) rotateX(${cardRotateX}deg) rotateY(${cardRotateY}deg)`,
              opacity: cardOpacity,
              position: "relative",
              overflow: "hidden",
              transition: "none",
            }}
          >
            {/* Card Glare effect */}
            <div
              style={{
                position: "absolute",
                top: 0,
                left: "-50%",
                width: "200%",
                height: "100%",
                background: "linear-gradient(115deg, transparent 20%, rgba(255,255,255,0.1) 40%, rgba(255,255,255,0.05) 60%, transparent 80%)",
                transform: `translateX(${interpolate(frame, [0, 150], [-20, 20])}%)`,
                transition: "none",
              }}
            />
            
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", transition: "none" }}>
              <span style={{ color: "white", fontSize: cardWidth * 0.07, fontWeight: 700, transition: "none" }}>
                {bankName}
              </span>
              {/* Contactless Icon */}
              <svg width={cardWidth * 0.1} height={cardWidth * 0.1} viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round" style={{ opacity: 0.8, transition: "none" }}>
                <path d="M8.5 21.5C10.5 19.5 11.5 16.5 11.5 13.5C11.5 10.5 10.5 7.5 8.5 5.5M12.5 23.5C15.5 20.5 17 17 17 13.5C17 10 15.5 6.5 12.5 3.5M16.5 25.5C20.5 21.5 22.5 17.5 22.5 13.5C22.5 9.5 20.5 5.5 16.5 1.5M4.5 19.5C5.5 18 6 16 6 13.5C6 11 5.5 9 4.5 7.5" />
              </svg>
            </div>
            
            {/* EMV Chip */}
            <div
              style={{
                width: cardWidth * 0.14,
                height: cardWidth * 0.1,
                background: "linear-gradient(135deg, #eab308 0%, #ca8a04 100%)",
                borderRadius: cardWidth * 0.02,
                marginTop: cardHeight * 0.15,
                transition: "none",
              }}
            />

            <div>
              <div style={{ color: "rgba(255,255,255,0.6)", fontSize: cardWidth * 0.04, marginBottom: cardWidth * 0.01, transition: "none" }}>
                {accountName}
              </div>
              <div style={{ color: "white", fontSize: cardWidth * 0.05, letterSpacing: "2px", transition: "none" }}>
                **** **** **** 4092
              </div>
            </div>
          </div>
        </div>

        {/* Right Side: Dashboard / Balance */}
        <div
          style={{
            flex: 1,
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            paddingLeft: safeZone,
            position: "relative",
            transition: "none",
          }}
        >
          {/* Background Graph Path */}
          <div style={{ position: "absolute", top: "50%", left: 0, width: "100%", height: "200px", transform: "translateY(-50%)", zIndex: 0, opacity: 0.15, transition: "none" }}>
            <svg width="100%" height="100%" viewBox="0 0 800 200" preserveAspectRatio="none">
              <path
                d="M 0 180 Q 200 180 300 120 T 500 80 T 800 20"
                fill="none"
                stroke={primaryColor}
                strokeWidth="12"
                strokeLinecap="round"
                strokeDasharray={pathLength}
                strokeDashoffset={dashOffset}
                style={{ transition: "none" }}
              />
            </svg>
          </div>

          <div style={{ zIndex: 1, transition: "none" }}>
            {/* Notification Pill */}
            <div
              style={{
                display: "inline-flex",
                alignItems: "center",
                backgroundColor: `${primaryColor}15`,
                padding: `${width * 0.008}px ${width * 0.015}px`,
                borderRadius: width * 0.05,
                transform: `translateY(${notifY}px)`,
                opacity: notifOpacity,
                marginBottom: width * 0.015,
                boxShadow: `0 4px 15px ${primaryColor}10`,
                transition: "none",
              }}
            >
              <div
                style={{
                  width: width * 0.02,
                  height: width * 0.02,
                  borderRadius: "50%",
                  backgroundColor: primaryColor,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  marginRight: width * 0.01,
                  transition: "none",
                }}
              >
                <svg width={width * 0.012} height={width * 0.012} viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" style={{ transition: "none" }}>
                  <line x1="12" y1="5" x2="12" y2="19"></line>
                  <polyline points="19 12 12 19 5 12"></polyline>
                </svg>
              </div>
              <span
                style={{
                  color: primaryColor,
                  fontWeight: 700,
                  fontSize: width * 0.018,
                  transition: "none",
                }}
              >
                Income Deposit +{currencySymbol}{depositAmount.toLocaleString()}
              </span>
            </div>

            <div
              style={{
                color: textColor,
                opacity: 0.6,
                fontSize: width * 0.02,
                fontWeight: 600,
                textTransform: "uppercase",
                letterSpacing: "1px",
                marginBottom: width * 0.005,
                transition: "none",
              }}
            >
              Total Balance
            </div>

            <div
              style={{
                color: textColor,
                fontSize: width * 0.07,
                fontWeight: 800,
                lineHeight: 1.1,
                transform: `scale(${bounceScale})`,
                transformOrigin: "left center",
                transition: "none",
              }}
            >
              {currencySymbol}{currentBalance.toLocaleString()}
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default IncomeDeposit;